import math

def verifier(assign):
    # Recompute the minimum using the hidden parameters to verify and enforce difficulty
    try:
        A = int(assign['A']); B = int(assign['B']); R = int(assign['R'])
        lam = int(assign['lambda'])
        r = int(assign['r']); t = int(assign['t'])
        p = int(assign['p']); s_num = int(assign['s_num']); s_den = int(assign['s_den'])
        u = int(assign['u']); v_num = int(assign['v_num']); v_den = int(assign['v_den'])
    except Exception:
        return (False, None)  # missing parameters

    # basic domain checks
    if not (A > 0 and B > 0 and R > 0 and R < min(A, B)):
        return (False, None)
    if not (p == 2 and s_num == 1 and s_den == 4 and u == 1 and v_num == 1 and v_den == 2):
        # only this family is supported by the proof and construction
        return (False, None)
    if lam not in (1, 2):
        # enforce nontrivial harder-than-seed perturbation
        return (False, None)

    C = A*A + B*B - R*R
    if C <= 0:
        return (False, None)

    # slope interval from tangents to the circle seen from the origin
    ak = R*R - A*A
    bk = 2*A*B
    ck = R*R - B*B
    disc = bk*bk - 4*ak*ck
    if disc <= 0:
        return (False, None)
    sqrt_disc = math.sqrt(disc)
    k1 = (-bk - sqrt_disc) / (2*ak)
    k2 = (-bk + sqrt_disc) / (2*ak)
    k_lo = min(k1, k2)
    k_hi = max(k1, k2)
    if not (k_lo > 0 and k_hi > 0 and k_lo < k_hi):
        return (False, None)

    def f_of_k(k):
        if k <= 0:
            return float('inf')
        Dk = (A + k*B)**2 - (1 + k*k)*C
        if Dk < 0:
            return float('inf')
        tmin = (A + k*B - math.sqrt(Dk)) / (1 + k*k)
        if tmin <= 0:
            return float('inf')
        Ck = ((1 + k*k) + lam*k) / math.sqrt(k)
        return Ck * tmin

    # Golden-section minimization inside the valid slope interval
    left = k_lo + 1e-12
    right = k_hi - 1e-12
    if not (left < right):
        return (False, None)

    gr = (math.sqrt(5) - 1) / 2
    a_, b_ = left, right
    c_ = b_ - gr*(b_ - a_)
    d_ = a_ + gr*(b_ - a_)
    fc = f_of_k(c_)
    fd = f_of_k(d_)
    iters = 0
    while b_ - a_ > 1e-13 and iters < 240:
        iters += 1
        if fc < fd:
            b_ = d_
            d_ = c_
            fd = fc
            c_ = b_ - gr*(b_ - a_)
            fc = f_of_k(c_)
        else:
            a_ = c_
            c_ = d_
            fc = fd
            d_ = a_ + gr*(b_ - a_)
            fd = f_of_k(d_)
    k_star = 0.5*(a_ + b_)
    ans = f_of_k(k_star)

    # enforce nontrivial interior minimum and reasonable scale
    if not (k_lo + 1e-6 < k_star < k_hi - 1e-6):
        return (False, None)
    if not (ans > 0):
        return (False, None)

    return True, ans
